SELECT CASE WHEN budget >= 3759000 THEN 'high' WHEN budget >= 2045000 THEN 'mid' ELSE 'low' END AS budget_bucket, COUNT(DISTINCT budget) AS unique_locations, AVG(budget) AS avg_budget FROM departments GROUP BY CASE WHEN budget >= 3759000 THEN 'high' WHEN budget >= 2045000 THEN 'mid' ELSE 'low' END ORDER BY unique_locations DESC
